import json
r=json.load(open('/workspace/runtime_context.json'))
print('TOP',list(r))
for k,v in r.items():
 if k not in ['context','study_schema']: print(k,json.dumps(v,indent=2))
c=r['context'];print('CONTEXT_KEYS',list(c))
for k,v in c.items():
 if k not in ['history','knowledge']: print(k,json.dumps(v,indent=2))
